//! The fullscreen element on the static path (miaskiewicz/turbo-dom#82): the live-geometry
//! Chrome 156 control's `fullscreen-*` cases (`tests/fixtures/live_geometry_chrome156.json`,
//! generated by turbo-dom's `scripts/live-geometry-chrome-control.mjs`, where a trusted click
//! puts the case's `fullscreen` element in fullscreen) laid out through [`layout_boxes_tree`]
//! with the same element reported in the tree's fullscreen stack, each `[data-cid]` box
//! compared with Chrome's `getBoundingClientRect()`. Without a fullscreen stack the same
//! documents lay out in flow (the UA rules cost nothing then).
use serde_json::Value;
use turbo_dom_layout::{
    layout_boxes_tree, parse_html_tree, Diagnostics, FontRegistry, HtmlOptions,
};

fn fullscreen_cases() -> Vec<Value> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/live_geometry_chrome156.json"
    );
    let fixture: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("the Chrome fixture")).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|case| case["fullscreen"].is_string())
        .cloned()
        .collect()
}

#[test]
#[ignore = "turbo-dom#82: fails until the fix"]
fn the_fullscreen_element_fills_the_viewport_on_the_static_path_like_chrome_156() {
    let fonts = FontRegistry::new();
    let cases = fullscreen_cases();
    assert!(cases.len() >= 4);
    let mut failures = Vec::new();
    for case in &cases {
        let id = case["id"].as_str().unwrap();
        let mut tree = parse_html_tree(case["html"].as_str().unwrap());
        let selector = format!("[data-cid=\"{}\"]", case["fullscreen"].as_str().unwrap());
        let element = tree.query_selector(&selector).unwrap();
        assert!(tree.set_fullscreen_stack(&[element]));
        let mut diags = Diagnostics::default();
        let got = layout_boxes_tree(
            &tree,
            "",
            1280.0,
            800.0,
            &fonts,
            &HtmlOptions::default(),
            &mut diags,
        );
        for want in case["boxes"].as_array().unwrap() {
            let cid = want["cid"].as_str().unwrap();
            let Some(b) = got.iter().find(|b| b.cid == cid) else {
                failures.push(format!("{id}: no box for data-cid={cid}"));
                continue;
            };
            for (field, value) in [
                ("x", b.x),
                ("y", b.y),
                ("width", b.width),
                ("height", b.height),
            ] {
                let chrome = want[field].as_f64().unwrap() as f32;
                if (value - chrome).abs() > 0.01 {
                    failures.push(format!("{id}: {cid}.{field} = {value}, Chrome {chrome}"));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences from Chrome 156:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
